## Code Example
```c
void handle_write_fault(PTE *pte) {
  acquire(pte->lock);
  if (pte->refcount > 1) {
    Page *newpage = alloc_page();
    memcpy(newpage->addr, pte->frame->addr, PAGE_SIZE);
    pte->frame = newpage;
    pte->writable = 1;
    pte->refcount--;
    invalidate_tlb(pte->vaddr);
  } else {
    pte->writable = 1;
  }
  release(pte->lock);
}
